-- ATOM Curriculum Library V3 — Complete Technical Expansion
-- Idempotent seed only: adds missing Blocks, Techniques and Situations without
-- renaming, moving, reactivating or overwriting existing Curriculum records.
--
-- V3 seed payload:
--   * 15 new Blocks
--   * 172 new Techniques
--   * 172 practical Situations / opponent reactions
--
-- After V1 + V2 + V3, the seed baseline contains 45 Blocks, 349 Techniques
-- and 274 Situations (before any academy-created custom content).
--
-- Level remains encoded in technique.description for this lot because the
-- current schema does not yet have a dedicated curriculum level column.
-- A separate Curriculum Level Enforcement lot will migrate this into
-- structured metadata and enforce Program-level filtering.

begin;

do $atom_curriculum_v3_blocks$
declare
  v_seed jsonb := $json$[{"type":"Takedowns","block":"Grip Fighting & Stance","block_sort":30,"description":"Standing posture, movement, grip acquisition and inside-position fundamentals for initiating takedowns.","techniques":[{"name":"Athletic Stance & Motion","level":"Beginner","sort":10},{"name":"Collar-Sleeve Grip Fighting","level":"Beginner · Gi","sort":20},{"name":"Wrist Control & Inside Tie","level":"Beginner · NoGi","sort":30},{"name":"Pummeling for Inside Position","level":"Beginner · NoGi","sort":40},{"name":"Grip Break to Entry","level":"Beginner","sort":50},{"name":"Two-on-One / Russian Tie","level":"Intermediate","sort":60},{"name":"Underhook to Body Lock","level":"Intermediate","sort":70}]},{"type":"Takedowns","block":"Single Leg System","block_sort":40,"description":"Single-leg entries, positional control and finishes from standing wrestling exchanges.","techniques":[{"name":"Penetration Step to Single Leg","level":"Beginner","sort":10},{"name":"Outside Single","level":"Beginner","sort":20},{"name":"Inside Single","level":"Beginner","sort":30},{"name":"Running the Pipe","level":"Beginner","sort":40},{"name":"Shelf Finish","level":"Intermediate","sort":50},{"name":"Tree Top Finish","level":"Intermediate","sort":60},{"name":"Crackdown Finish","level":"Advanced","sort":70},{"name":"Single Leg to Back Body Lock","level":"Intermediate","sort":80}]},{"type":"Takedowns","block":"Body Lock / Upper-Body Takedowns","block_sort":50,"description":"Inside-control takedowns from underhooks, body locks and upper-body clinch positions.","techniques":[{"name":"Body Lock Entry","level":"Beginner","sort":10},{"name":"Pummeling to Body Lock","level":"Beginner","sort":20},{"name":"Outside Trip","level":"Intermediate","sort":30},{"name":"Inside Trip","level":"Intermediate","sort":40},{"name":"Mat Return","level":"Intermediate","sort":50},{"name":"Back Body Lock Takedown","level":"Intermediate","sort":60},{"name":"Hip Toss from Over-Under","level":"Intermediate","sort":70}]},{"type":"Takedowns","block":"Foot Sweeps","block_sort":60,"description":"Timing-based standing off-balancing and foot-sweep systems from common grappling grips.","techniques":[{"name":"De Ashi Barai","level":"Intermediate","sort":10},{"name":"Ko Uchi Gari","level":"Intermediate","sort":20},{"name":"O Uchi Gari","level":"Intermediate","sort":30},{"name":"Sasae Tsurikomi Ashi","level":"Intermediate","sort":40},{"name":"Kosoto Gake","level":"Intermediate","sort":50},{"name":"Foot Sweep from Collar Tie","level":"Intermediate · NoGi","sort":60}]},{"type":"Guard Systems","block":"Spider Guard","block_sort":160,"description":"Double-sleeve and foot-on-arm control for distance management, sweeps, submissions and transitions.","techniques":[{"name":"Double-Sleeve Spider Control","level":"Intermediate · Gi","sort":10},{"name":"Spider Guard Retention","level":"Intermediate · Gi","sort":20},{"name":"Tripod Sweep","level":"Intermediate · Gi","sort":30},{"name":"Lasso Transition","level":"Intermediate · Gi","sort":40},{"name":"Omoplata Entry","level":"Intermediate · Gi","sort":50},{"name":"Triangle Entry","level":"Intermediate · Gi","sort":60},{"name":"Back Take Transition","level":"Advanced · Gi","sort":70}]},{"type":"Guard Systems","block":"Knee Shield / Z Guard","block_sort":170,"description":"Half-guard framing system using knee shield distance, underhooks and wrestle-up transitions.","techniques":[{"name":"Knee Shield Frames & Distance","level":"Beginner","sort":10},{"name":"Underhook Entry","level":"Beginner","sort":20},{"name":"Old School Sweep","level":"Intermediate","sort":30},{"name":"Knee Tap Sweep","level":"Intermediate","sort":40},{"name":"Dogfight Entry","level":"Intermediate","sort":50},{"name":"Kimura Trap","level":"Intermediate","sort":60},{"name":"Back Take Transition","level":"Advanced","sort":70}]},{"type":"Guard Systems","block":"Guard Retention","block_sort":180,"description":"Foundational retention mechanics for maintaining or recovering guard against common passing directions.","techniques":[{"name":"Hip Frame Retention","level":"Beginner","sort":10},{"name":"Knee-Elbow Connection","level":"Beginner","sort":20},{"name":"Inside Position Recovery","level":"Beginner","sort":30},{"name":"Pummel Feet Inside","level":"Beginner","sort":40},{"name":"Half Guard Recovery","level":"Beginner","sort":50},{"name":"DLR Recovery","level":"Intermediate","sort":60},{"name":"Granby Recovery","level":"Intermediate","sort":70},{"name":"Inversion Retention","level":"Advanced","sort":80}]},{"type":"Guard Systems","block":"Seated Guard","block_sort":190,"description":"Open seated-guard posture, connection, wrestle-up and transition systems against standing or kneeling opponents.","techniques":[{"name":"Seated Guard Stance & Frames","level":"Beginner","sort":10},{"name":"Shin-to-Shin Entry","level":"Beginner","sort":20},{"name":"Butterfly Entry","level":"Beginner","sort":30},{"name":"Arm Drag","level":"Intermediate","sort":40},{"name":"Single Leg Wrestle-Up","level":"Intermediate","sort":50},{"name":"DLR Entry","level":"Intermediate","sort":60},{"name":"Single Leg X Entry","level":"Intermediate","sort":70}]},{"type":"Passing","block":"Headquarters Passing","block_sort":50,"description":"Central standing passing hub using inside position, knee-line control and directional transitions.","techniques":[{"name":"Headquarters Entry","level":"Beginner","sort":10},{"name":"Inside Position Control","level":"Beginner","sort":20},{"name":"Knee Cut from Headquarters","level":"Intermediate","sort":30},{"name":"Smash Pass from Headquarters","level":"Intermediate","sort":40},{"name":"Leg Drag from Headquarters","level":"Intermediate","sort":50},{"name":"Backstep from Headquarters","level":"Intermediate","sort":60},{"name":"Long Step Pass","level":"Intermediate","sort":70}]},{"type":"Passing","block":"Body Lock Passing","block_sort":60,"description":"Pressure passing from upper-body connection against seated, butterfly and open guards.","techniques":[{"name":"Body Lock Entry","level":"Intermediate","sort":10},{"name":"Head Position & Hip Connection","level":"Intermediate","sort":20},{"name":"Butterfly Flattening","level":"Intermediate","sort":30},{"name":"Double-Under Body Lock","level":"Intermediate","sort":40},{"name":"Knee Pin Finish","level":"Intermediate","sort":50},{"name":"Half Guard Finish","level":"Intermediate","sort":60},{"name":"Back Take Transition","level":"Advanced","sort":70}]},{"type":"Passing","block":"Leg Drag Passing","block_sort":70,"description":"Hip-control passing system built around redirecting the legs and exposing the outside hip.","techniques":[{"name":"Leg Drag Entry","level":"Intermediate","sort":10},{"name":"Hip Control & Pin","level":"Intermediate","sort":20},{"name":"Side-to-Side Leg Drag","level":"Intermediate","sort":30},{"name":"DLR Leg Drag","level":"Intermediate","sort":40},{"name":"X Guard Leg Drag","level":"Advanced","sort":50},{"name":"Knee Cut Transition","level":"Intermediate","sort":60},{"name":"Back Take Transition","level":"Advanced","sort":70}]},{"type":"Escapes","block":"Knee-on-Belly Escapes","block_sort":50,"description":"Defensive framing and positional recovery against knee-on-belly control.","techniques":[{"name":"Frame & Hip Escape","level":"Beginner","sort":10},{"name":"Elbow-Knee Recovery","level":"Beginner","sort":20},{"name":"Bridge to Guard Recovery","level":"Beginner","sort":30},{"name":"Underhook Escape","level":"Intermediate","sort":40},{"name":"Single Leg Recovery","level":"Intermediate","sort":50}]},{"type":"Escapes","block":"North-South Escapes","block_sort":60,"description":"Escapes and guard-recovery options from north-south chest and hip control.","techniques":[{"name":"Frame & Hip Turn","level":"Beginner","sort":10},{"name":"Elbow Escape","level":"Beginner","sort":20},{"name":"Underhook Recovery","level":"Intermediate","sort":30},{"name":"Pendulum Escape","level":"Intermediate","sort":40},{"name":"Turtle Recovery","level":"Intermediate","sort":50}]},{"type":"Escapes","block":"Front Headlock Escapes","block_sort":70,"description":"Posture recovery, hand fighting and re-attacks from front-headlock defensive positions.","techniques":[{"name":"Posture & Hand Fight","level":"Beginner","sort":10},{"name":"Two-on-One Wrist Peel","level":"Beginner","sort":20},{"name":"Guard Pull Recovery","level":"Beginner","sort":30},{"name":"Peek-Out","level":"Intermediate","sort":40},{"name":"Sit-Out","level":"Intermediate","sort":50},{"name":"Single Leg Re-Attack","level":"Intermediate","sort":60},{"name":"Roll-Through Escape","level":"Advanced","sort":70}]},{"type":"Submissions","block":"Turtle Attacks","block_sort":60,"description":"Breakdowns, rides, back-take routes and submissions against the turtle position.","techniques":[{"name":"Turtle Breakdown to Side Control","level":"Beginner","sort":10},{"name":"Seatbelt Entry","level":"Beginner","sort":20},{"name":"Back Take","level":"Intermediate","sort":30},{"name":"Spiral Ride","level":"Intermediate","sort":40},{"name":"Clock Choke","level":"Intermediate · Gi","sort":50},{"name":"Crucifix Entry","level":"Advanced","sort":60},{"name":"Anaconda Transition","level":"Intermediate","sort":70}]},{"type":"Takedowns","block":"Takedowns","block_sort":10,"description":"Standing takedown entries and finishes.","techniques":[{"name":"Arm Drag to Single Leg","level":"Intermediate","sort":80},{"name":"Duck Under","level":"Intermediate","sort":90},{"name":"Snapdown to Go Behind","level":"Beginner","sort":100},{"name":"Knee Tap","level":"Intermediate","sort":110}]},{"type":"Takedowns","block":"Takedown Defense / Counters","block_sort":20,"description":"Standing takedown defense and counter-offense.","techniques":[{"name":"Sprawl to Front Headlock","level":"Beginner","sort":70},{"name":"Whizzer Kick Counter","level":"Intermediate","sort":80},{"name":"Single Leg Granby Escape","level":"Advanced","sort":90}]},{"type":"Guard Systems","block":"Closed Guard","block_sort":10,"description":"Closed guard control, sweeps, submissions and back takes.","techniques":[{"name":"Flower Sweep","level":"Beginner","sort":70},{"name":"Pendulum Sweep","level":"Intermediate","sort":80},{"name":"Cross-Collar Choke","level":"Beginner · Gi","sort":90},{"name":"Omoplata","level":"Intermediate","sort":100},{"name":"Hip Bump to Kimura","level":"Intermediate","sort":110}]},{"type":"Guard Systems","block":"Sit Up Guard","block_sort":20,"description":"ATOM sit-up guard system.","techniques":[{"name":"Sit Up Collar Drag","level":"Intermediate · Gi","sort":70},{"name":"Sit Up Wrestle-Up","level":"Intermediate","sort":80}]},{"type":"Guard Systems","block":"De La Riva","block_sort":30,"description":"De La Riva control, sweeps and transitions.","techniques":[{"name":"Sickle Sweep","level":"Intermediate","sort":80},{"name":"DLR to Shin-to-Shin","level":"Intermediate","sort":90}]},{"type":"Guard Systems","block":"Deep De La Riva","block_sort":40,"description":"Deep De La Riva off-balancing and back exposure.","techniques":[{"name":"Deep DLR to Waiter Guard","level":"Advanced","sort":60},{"name":"Deep DLR to Leg Drag","level":"Advanced","sort":70}]},{"type":"Guard Systems","block":"Shallow Guard","block_sort":50,"description":"ATOM Shallow Guard system.","techniques":[{"name":"Wrestle-Up Transition","level":"Intermediate","sort":70},{"name":"Shallow to Single Leg X","level":"Intermediate","sort":80}]},{"type":"Guard Systems","block":"Waiter Guard","block_sort":60,"description":"Waiter guard sweeps and transitions.","techniques":[{"name":"Waiter to Leg Drag","level":"Advanced","sort":50},{"name":"Waiter to Deep Half","level":"Intermediate","sort":60}]},{"type":"Guard Systems","block":"Double Pull / Berimbolo","block_sort":70,"description":"Double-pull, berimbolo and crab-ride system.","techniques":[{"name":"Baby Bolo Entry","level":"Advanced","sort":70},{"name":"Crab Ride Back Take","level":"Advanced","sort":80}]},{"type":"Guard Systems","block":"Butterfly Guard","block_sort":80,"description":"Butterfly guard hooks, sweeps and transitions.","techniques":[{"name":"Shoulder Crunch Sweep","level":"Intermediate","sort":70},{"name":"Elevation Sweep","level":"Intermediate","sort":80},{"name":"Guillotine Entry","level":"Intermediate · NoGi","sort":90}]},{"type":"Guard Systems","block":"Half Guard","block_sort":90,"description":"Half guard framing, underhook and sweep systems.","techniques":[{"name":"Underhook Knee Tap Sweep","level":"Intermediate","sort":70},{"name":"John Wayne Sweep","level":"Intermediate","sort":80},{"name":"Lockdown Sweep","level":"Intermediate","sort":90}]},{"type":"Guard Systems","block":"Deep Half Guard","block_sort":100,"description":"Deep half guard control, sweeps and back takes.","techniques":[{"name":"Deep Half to Single Leg","level":"Intermediate","sort":70},{"name":"Deep Half to X Guard","level":"Advanced","sort":80}]},{"type":"Guard Systems","block":"Collar Sleeve Guard","block_sort":110,"description":"Collar-and-sleeve open guard.","techniques":[{"name":"Arm Drag","level":"Intermediate · Gi","sort":80},{"name":"Tomoe Nage Sweep","level":"Intermediate · Gi","sort":90}]},{"type":"Guard Systems","block":"Lasso Guard","block_sort":120,"description":"Lasso control, sweeps and transitions.","techniques":[{"name":"Lasso to Single Leg X","level":"Intermediate · Gi","sort":80},{"name":"Lasso to Leg Drag Sweep","level":"Advanced · Gi","sort":90}]},{"type":"Guard Systems","block":"Reverse De La Riva","block_sort":130,"description":"Reverse De La Riva control and inversion.","techniques":[{"name":"RDLR to Single Leg X","level":"Intermediate","sort":70},{"name":"RDLR Wrestle-Up","level":"Intermediate","sort":80}]},{"type":"Guard Systems","block":"Single Leg X","block_sort":140,"description":"Single-leg X control, sweeps and transitions.","techniques":[{"name":"SLX Technical Stand-Up","level":"Intermediate","sort":70},{"name":"SLX to Wrestle-Up","level":"Intermediate","sort":80}]},{"type":"Guard Systems","block":"X Guard","block_sort":150,"description":"X guard control, sweeps and transitions.","techniques":[{"name":"X Guard Knee Tap","level":"Intermediate","sort":70},{"name":"X Guard to Leg Drag","level":"Advanced","sort":80}]},{"type":"Passing","block":"Open Guard Passing","block_sort":10,"description":"Core open-guard passing.","techniques":[{"name":"X-Pass","level":"Intermediate","sort":70},{"name":"Long Step","level":"Intermediate","sort":80},{"name":"Folding Pass","level":"Intermediate","sort":90}]},{"type":"Passing","block":"De La Riva Passing","block_sort":20,"description":"Passing against De La Riva guard.","techniques":[{"name":"Shin Staple","level":"Intermediate","sort":60},{"name":"Headquarters Transition","level":"Intermediate","sort":70}]},{"type":"Passing","block":"Under-Over Passing","block_sort":30,"description":"Under-over pressure passing.","techniques":[{"name":"Double Under Transition","level":"Intermediate","sort":60},{"name":"Leg Drag Finish","level":"Intermediate","sort":70}]},{"type":"Passing","block":"Half Guard Passing","block_sort":40,"description":"Half guard pressure passing.","techniques":[{"name":"Reverse Half Guard Pass","level":"Intermediate","sort":70},{"name":"Mount Transition","level":"Intermediate","sort":80}]},{"type":"Escapes","block":"Side Control Escapes","block_sort":10,"description":"Side-control escape and guard recovery.","techniques":[{"name":"Running Man / Defensive Shell","level":"Intermediate","sort":70},{"name":"Elbow Push Escape","level":"Intermediate","sort":80}]},{"type":"Escapes","block":"Mount Escapes","block_sort":20,"description":"Mount escape and recovery.","techniques":[{"name":"Back Door Escape","level":"Intermediate","sort":60},{"name":"Heel Drag Recovery","level":"Intermediate","sort":70}]},{"type":"Escapes","block":"Back Escapes","block_sort":30,"description":"Back-control escape and guard recovery.","techniques":[{"name":"Turn-In Escape","level":"Intermediate","sort":60},{"name":"Body Triangle Escape","level":"Advanced","sort":70}]},{"type":"Escapes","block":"Turtle Escapes / Recovery","block_sort":40,"description":"Turtle recovery and re-attack.","techniques":[{"name":"Stand-Up Recovery","level":"Beginner","sort":70},{"name":"Switch / Sit-Out Reversal","level":"Intermediate","sort":80}]},{"type":"Submissions","block":"Back Attacks","block_sort":10,"description":"Back control and submission attacks.","techniques":[{"name":"Straightjacket Control","level":"Intermediate","sort":70},{"name":"Body Triangle Control","level":"Intermediate","sort":80},{"name":"Rear Triangle","level":"Advanced","sort":90}]},{"type":"Submissions","block":"Front Headlock","block_sort":20,"description":"Front-headlock control and submission system.","techniques":[{"name":"Snapdown Entry","level":"Beginner","sort":80},{"name":"Chin Strap Go Behind","level":"Intermediate","sort":90}]},{"type":"Submissions","block":"Side Control Attacks","block_sort":30,"description":"Side-control attacks and transitions.","techniques":[{"name":"Baseball Bat Choke","level":"Intermediate · Gi","sort":70},{"name":"Knee-on-Belly Transition","level":"Beginner","sort":80}]},{"type":"Submissions","block":"Mount Attacks","block_sort":40,"description":"Mount control, submissions and back takes.","techniques":[{"name":"Mounted Triangle","level":"Advanced","sort":70},{"name":"Gift Wrap Back Take","level":"Intermediate","sort":80}]},{"type":"Submissions","block":"North-South Attacks","block_sort":50,"description":"North-south control and attacks.","techniques":[{"name":"Paper Cutter Transition","level":"Intermediate · Gi","sort":60},{"name":"Head-and-Arm Transition","level":"Intermediate","sort":70}]}]$json$::jsonb;
  v_block jsonb;
  v_technique jsonb;
  v_type_id uuid;
  v_block_id uuid;
  v_existing_block_type_id uuid;
  v_type_name text;
  v_block_name text;
  v_block_description text;
  v_technique_name text;
  v_level text;
  v_block_sort integer;
  v_technique_sort integer;
begin
  for v_block in
    select value from jsonb_array_elements(v_seed)
  loop
    v_type_name := btrim(v_block ->> 'type');
    v_block_name := btrim(v_block ->> 'block');
    v_block_description := nullif(btrim(v_block ->> 'description'), '');
    v_block_sort := coalesce((v_block ->> 'block_sort')::integer, 100);

    select t.id
      into v_type_id
    from public.coach_curriculum_types t
    where lower(t.name) = lower(v_type_name)
    order by t.is_active desc, t.created_at asc
    limit 1;

    if v_type_id is null then
      raise exception 'ATOM Curriculum V3 seed failed: technical type "%" was not found.', v_type_name;
    end if;

    -- Prefer the intended Technical Type. If the exact Block name already
    -- exists elsewhere, reuse it rather than creating an accidental duplicate.
    select b.id, b.type_id
      into v_block_id, v_existing_block_type_id
    from public.coach_curriculum_blocks b
    where lower(b.name) = lower(v_block_name)
    order by
      case when b.type_id = v_type_id then 0 else 1 end,
      b.is_active desc,
      b.created_at asc
    limit 1;

    if v_block_id is null then
      insert into public.coach_curriculum_blocks (
        type_id, name, description, sort_order, is_active
      )
      values (
        v_type_id, v_block_name, v_block_description, v_block_sort, true
      )
      returning id, type_id into v_block_id, v_existing_block_type_id;
    end if;

    for v_technique in
      select value from jsonb_array_elements(v_block -> 'techniques')
    loop
      v_technique_name := btrim(v_technique ->> 'name');
      v_level := nullif(btrim(v_technique ->> 'level'), '');
      v_technique_sort := coalesce((v_technique ->> 'sort')::integer, 100);

      if not exists (
        select 1
        from public.coach_curriculum_techniques ct
        where ct.block_id = v_block_id
          and lower(ct.name) = lower(v_technique_name)
      ) then
        insert into public.coach_curriculum_techniques (
          block_id, name, description, sort_order, is_active
        )
        values (
          v_block_id,
          v_technique_name,
          case
            when v_level is null then 'ATOM Curriculum V3'
            else 'ATOM Curriculum V3 · ' || v_level
          end,
          v_technique_sort,
          true
        );
      end if;
    end loop;
  end loop;
end
$atom_curriculum_v3_blocks$;

do $atom_curriculum_v3_situations$
declare
  v_seed jsonb := $json$[{"type":"Takedowns","block":"Grip Fighting & Stance","technique":"Athletic Stance & Motion","name":"Opponent changes level while circling","reaction":"Opponent circles and repeatedly changes level to provoke an upright reaction.","response":"Keep head over hips, hands ready to frame, and move the feet before reaching so the stance stays available for offense and defense.","sort":10},{"type":"Takedowns","block":"Grip Fighting & Stance","technique":"Collar-Sleeve Grip Fighting","name":"Opponent establishes dominant collar grip","reaction":"Opponent secures a strong collar grip first and pulls the posture forward.","response":"Control the gripping wrist, rebuild posture and clear or neutralize the collar before committing to your own entry.","sort":20},{"type":"Takedowns","block":"Grip Fighting & Stance","technique":"Wrist Control & Inside Tie","name":"Opponent retracts the controlled wrist","reaction":"Opponent pulls the wrist back and squares the shoulders.","response":"Follow with inside position rather than chasing the hand, then connect the tie to a level change or angle.","sort":30},{"type":"Takedowns","block":"Grip Fighting & Stance","technique":"Pummeling for Inside Position","name":"Opponent wins the first underhook","reaction":"Opponent secures one underhook and starts turning the shoulders.","response":"Frame the head and opposite shoulder, circle to recover inside position and re-pummel before attacking.","sort":40},{"type":"Takedowns","block":"Grip Fighting & Stance","technique":"Grip Break to Entry","name":"Opponent stiff-arms after the grip break","reaction":"Opponent extends the arm immediately after the grip is cleared to restore distance.","response":"Use the extended arm as a line to angle in and connect the takedown entry before the grip is rebuilt.","sort":50},{"type":"Takedowns","block":"Grip Fighting & Stance","technique":"Two-on-One / Russian Tie","name":"Opponent squares the elbow back to the ribs","reaction":"Opponent pulls the controlled elbow tight and turns toward you.","response":"Keep shoulder connection, step to the outside angle and transition to single leg, snapdown or back-body-lock access.","sort":60},{"type":"Takedowns","block":"Grip Fighting & Stance","technique":"Underhook to Body Lock","name":"Opponent applies a strong overhook","reaction":"Opponent clamps a whizzer and widens the base to deny the body lock.","response":"Keep head position, lower the lock below the elbows and circle toward the underhook side before finishing the connection.","sort":70},{"type":"Takedowns","block":"Single Leg System","technique":"Penetration Step to Single Leg","name":"Opponent pulls the lead leg back","reaction":"Opponent reacts to the level change by retracting the lead leg.","response":"Continue the angle instead of reaching, connect to the far leg or transition to the outside single.","sort":10},{"type":"Takedowns","block":"Single Leg System","technique":"Outside Single","name":"Opponent turns the knee outward","reaction":"Opponent rotates the captured knee outward and pushes the head away.","response":"Keep the leg tight to the chest, win head position and move to the finish before the foot returns to the floor.","sort":20},{"type":"Takedowns","block":"Single Leg System","technique":"Inside Single","name":"Opponent applies a whizzer","reaction":"Opponent secures a strong overhook and leans weight into the shoulder.","response":"Stand posture, keep the leg shelf and circle away from the whizzer pressure before choosing the finish.","sort":30},{"type":"Takedowns","block":"Single Leg System","technique":"Running the Pipe","name":"Opponent hops and keeps balance","reaction":"Opponent stays upright on one leg and follows the circular motion.","response":"Change the angle of the trapped knee, keep the hip close and redirect the finish rather than pulling straight down.","sort":40},{"type":"Takedowns","block":"Single Leg System","technique":"Shelf Finish","name":"Opponent pushes the head to the outside","reaction":"Opponent uses the hands to force the head away while hopping.","response":"Keep chest-to-thigh connection, elevate the leg on the shelf and step to the finishing angle before lowering the level.","sort":50},{"type":"Takedowns","block":"Single Leg System","technique":"Tree Top Finish","name":"Opponent posts on your shoulders","reaction":"Opponent extends both arms and tries to keep the torso away while the leg is elevated.","response":"Keep the captured leg high, step under the hips and turn the knee line so the post cannot restore balance.","sort":60},{"type":"Takedowns","block":"Single Leg System","technique":"Crackdown Finish","name":"Opponent sprawls chest over the back","reaction":"Opponent drives the hips down and forces the single-leg position toward the mat.","response":"Turn the corner to the crackdown angle, keep the knee trapped and use hip position to come behind rather than lifting.","sort":70},{"type":"Takedowns","block":"Single Leg System","technique":"Single Leg to Back Body Lock","name":"Opponent turns away to free the leg","reaction":"Opponent rotates the hips away and exposes the back while pulling the captured leg free.","response":"Release the leg at the right moment, connect hands around the waist and climb to a stable back body lock.","sort":80},{"type":"Takedowns","block":"Body Lock / Upper-Body Takedowns","technique":"Body Lock Entry","name":"Opponent keeps elbows tight","reaction":"Opponent closes the elbows and blocks direct access around the waist.","response":"Use inside ties and head position to open the elbow line before connecting the hands lower on the torso.","sort":10},{"type":"Takedowns","block":"Body Lock / Upper-Body Takedowns","technique":"Pummeling to Body Lock","name":"Opponent mirrors every pummel","reaction":"Opponent repeatedly re-pummels and prevents a stable double-under position.","response":"Create a directional step or snap first, then pummel during the reaction instead of exchanging in place.","sort":20},{"type":"Takedowns","block":"Body Lock / Upper-Body Takedowns","technique":"Outside Trip","name":"Opponent widens the outside foot","reaction":"Opponent steps the target foot away and creates a wider base.","response":"Pull the upper body over the planted leg, step deeper and switch to an inside trip or mat return if the leg is no longer available.","sort":30},{"type":"Takedowns","block":"Body Lock / Upper-Body Takedowns","technique":"Inside Trip","name":"Opponent steps the leg back","reaction":"Opponent retracts the inside leg as the reap starts.","response":"Maintain the upper-body connection, follow the retreating step and redirect to outside trip or back-body-lock control.","sort":40},{"type":"Takedowns","block":"Body Lock / Upper-Body Takedowns","technique":"Mat Return","name":"Opponent tripod-posts forward","reaction":"Opponent bends at the waist and posts the hands to prevent being returned to the mat.","response":"Keep the lock below the elbows, control one side of the hips and return at an angle rather than lifting directly backward.","sort":50},{"type":"Takedowns","block":"Body Lock / Upper-Body Takedowns","technique":"Back Body Lock Takedown","name":"Opponent lowers the hips","reaction":"Opponent drops the center of gravity and widens the base from rear body lock.","response":"Stay connected, step to one side and attack the near leg or mat return instead of trying to lift through the base.","sort":60},{"type":"Takedowns","block":"Body Lock / Upper-Body Takedowns","technique":"Hip Toss from Over-Under","name":"Opponent circles away from the hip","reaction":"Opponent steps around the loading hip to prevent the throw.","response":"Keep upper-body connection and convert the rotation into an outside trip or back-body-lock angle.","sort":70},{"type":"Takedowns","block":"Foot Sweeps","technique":"De Ashi Barai","name":"Opponent plants the foot heavily","reaction":"Opponent stops stepping and loads weight onto the foot you intended to sweep.","response":"Do not force the sweep; create movement again and attack when the foot becomes light during the next step.","sort":10},{"type":"Takedowns","block":"Foot Sweeps","technique":"Ko Uchi Gari","name":"Opponent retracts the inside foot","reaction":"Opponent pulls the targeted foot back as the inside reap starts.","response":"Follow the weight shift to the opposite leg and combine with a forward attack or outside sweep.","sort":20},{"type":"Takedowns","block":"Foot Sweeps","technique":"O Uchi Gari","name":"Opponent widens the base","reaction":"Opponent steps wide and braces the upper body to stop the reap.","response":"Drive the upper body diagonally, keep chest connection and transition to body lock or knee tap if the leg is no longer light.","sort":30},{"type":"Takedowns","block":"Foot Sweeps","technique":"Sasae Tsurikomi Ashi","name":"Opponent steps around the blocking foot","reaction":"Opponent circles the lead foot around the block to recover balance.","response":"Maintain steering grips and continue the turn into a follow-up foot sweep or snapdown angle.","sort":40},{"type":"Takedowns","block":"Foot Sweeps","technique":"Kosoto Gake","name":"Opponent shifts weight off the near heel","reaction":"Opponent senses the outside hook and moves weight to the far leg.","response":"Use the transfer to attack the far leg or connect to the upper-body trip on the new base.","sort":50},{"type":"Takedowns","block":"Foot Sweeps","technique":"Foot Sweep from Collar Tie","name":"Opponent stiffens the collar tie","reaction":"Opponent posts the forearm and resists being pulled into motion.","response":"Circle the head, create a lateral step and sweep during the recovery step rather than against a stationary base.","sort":60},{"type":"Guard Systems","block":"Spider Guard","technique":"Double-Sleeve Spider Control","name":"Opponent pulls both elbows behind the knees","reaction":"Opponent retracts the elbows and tries to shorten your leg extension.","response":"Keep sleeve connection, angle the hips and alternate foot pressure so at least one arm remains extended.","sort":10},{"type":"Guard Systems","block":"Spider Guard","technique":"Spider Guard Retention","name":"Opponent circles to one side","reaction":"Opponent moves around one extended leg and tries to collapse the outside knee.","response":"Follow with the hips, recover the inside foot and rebuild square sleeve-and-foot alignment before attacking.","sort":20},{"type":"Guard Systems","block":"Spider Guard","technique":"Tripod Sweep","name":"Opponent steps the free leg far back","reaction":"Opponent removes the secondary base leg from sweep range.","response":"Use the extended distance to sit up, change angle and connect to technical stand-up or another open-guard transition.","sort":30},{"type":"Guard Systems","block":"Spider Guard","technique":"Lasso Transition","name":"Opponent bends the controlled elbow","reaction":"Opponent folds the sleeve arm and brings the elbow close to the ribs.","response":"Use the shortened elbow to thread the lasso deeper while keeping the opposite sleeve controlled.","sort":40},{"type":"Guard Systems","block":"Spider Guard","technique":"Omoplata Entry","name":"Opponent turns the shoulder inward","reaction":"Opponent rotates the controlled shoulder toward the center to deny the hip angle.","response":"Create lateral hip angle first, extend the far sleeve and enter the omoplata only after the shoulder line opens.","sort":50},{"type":"Guard Systems","block":"Spider Guard","technique":"Triangle Entry","name":"Opponent posts one knee between the hips","reaction":"Opponent drives a knee forward and narrows the space for the leg to clear the shoulder.","response":"Off-balance to the opposite side, clear the posting arm and then rotate the hips into the triangle line.","sort":60},{"type":"Guard Systems","block":"Spider Guard","technique":"Back Take Transition","name":"Opponent turns away to escape sleeve pressure","reaction":"Opponent rotates the shoulders and exposes the far side while trying to free a sleeve.","response":"Follow the turn, keep one sleeve and connect to the hip before climbing behind the shoulders.","sort":70},{"type":"Guard Systems","block":"Knee Shield / Z Guard","technique":"Knee Shield Frames & Distance","name":"Opponent collapses the knee shield","reaction":"Opponent drives chest pressure into the top knee and tries to connect crossface control.","response":"Rebuild elbow-knee frame, turn onto the side and recover head position before seeking the underhook.","sort":10},{"type":"Guard Systems","block":"Knee Shield / Z Guard","technique":"Underhook Entry","name":"Opponent wins the crossface first","reaction":"Opponent controls the head and flattens the shoulders before the underhook is established.","response":"Frame the neck and biceps, create hip space and recover side posture before pummeling the underhook.","sort":20},{"type":"Guard Systems","block":"Knee Shield / Z Guard","technique":"Old School Sweep","name":"Opponent posts the far leg wide","reaction":"Opponent widens the far base to prevent the roll toward the trapped side.","response":"Use the wide post to come up to the dogfight and change the finish instead of pulling from underneath.","sort":30},{"type":"Guard Systems","block":"Knee Shield / Z Guard","technique":"Knee Tap Sweep","name":"Opponent turns the knee away","reaction":"Opponent rotates the near knee outward to hide the knee-tap line.","response":"Keep upper-body underhook control and switch to the far-leg or back-take direction.","sort":40},{"type":"Guard Systems","block":"Knee Shield / Z Guard","technique":"Dogfight Entry","name":"Opponent whizzers heavily","reaction":"Opponent applies a strong overhook and drives the shoulder down.","response":"Keep head higher than the opponent's, stay connected to the near leg and build base before choosing the sweep.","sort":50},{"type":"Guard Systems","block":"Knee Shield / Z Guard","technique":"Kimura Trap","name":"Opponent grips hands together","reaction":"Opponent connects the hands to prevent shoulder rotation.","response":"Use the grip as a control point, change hip angle and transition to sweep or back take rather than forcing the arm.","sort":60},{"type":"Guard Systems","block":"Knee Shield / Z Guard","technique":"Back Take Transition","name":"Opponent turns away from the underhook","reaction":"Opponent rotates the torso away and exposes the far hip.","response":"Follow the hip, control the waist and climb behind the shoulders before releasing the half-guard connection.","sort":70},{"type":"Guard Systems","block":"Guard Retention","technique":"Hip Frame Retention","name":"Opponent closes chest-to-hip distance","reaction":"Opponent drives the hips forward and removes the space needed for the feet.","response":"Frame the shoulders or hips first, shift the pelvis away and reinsert the knees before extending the legs.","sort":10},{"type":"Guard Systems","block":"Guard Retention","technique":"Knee-Elbow Connection","name":"Opponent separates the knee from the elbow","reaction":"Opponent controls the near knee and pulls it away from the defensive elbow line.","response":"Turn the hip, reconnect elbow to knee and use the far leg to pummel back inside.","sort":20},{"type":"Guard Systems","block":"Guard Retention","technique":"Inside Position Recovery","name":"Opponent wins both inside knee lines","reaction":"Opponent places both knees or feet inside your legs and starts collapsing the hips.","response":"Frame upper body, create lateral hip movement and recover one inside hook before trying to square completely.","sort":30},{"type":"Guard Systems","block":"Guard Retention","technique":"Pummel Feet Inside","name":"Opponent pins one ankle to the mat","reaction":"Opponent controls one ankle and prevents that foot from returning inside.","response":"Use the free leg and hip movement to create space, then circle the trapped foot inside rather than pulling straight back.","sort":40},{"type":"Guard Systems","block":"Guard Retention","technique":"Half Guard Recovery","name":"Opponent clears one knee line","reaction":"Opponent passes one leg but leaves the lower leg within reach.","response":"Capture the remaining leg immediately, turn onto the side and establish frames before the upper body settles.","sort":50},{"type":"Guard Systems","block":"Guard Retention","technique":"DLR Recovery","name":"Opponent stands with one lead leg exposed","reaction":"Opponent has not completed chest connection and leaves the lead ankle near your hip.","response":"Reconnect ankle control, insert the DLR hook and square the shoulders before attacking.","sort":60},{"type":"Guard Systems","block":"Guard Retention","technique":"Granby Recovery","name":"Opponent circles behind the hips","reaction":"Opponent clears the legs and begins moving toward back exposure.","response":"Protect the neck, lead with the near shoulder and roll the hips through to recover facing guard.","sort":70},{"type":"Guard Systems","block":"Guard Retention","technique":"Inversion Retention","name":"Opponent redirects both legs to one side","reaction":"Opponent controls the ankles and moves them past the hip line.","response":"Keep shoulders connected to the mat, invert under the passing line and return the knees between the bodies.","sort":80},{"type":"Guard Systems","block":"Seated Guard","technique":"Seated Guard Stance & Frames","name":"Opponent rushes forward","reaction":"Opponent closes distance quickly and tries to force the shoulders backward.","response":"Post or frame without locking the elbow, keep the head over hips and connect shin or butterfly hooks before being flattened.","sort":10},{"type":"Guard Systems","block":"Seated Guard","technique":"Shin-to-Shin Entry","name":"Opponent steps the lead leg away","reaction":"Opponent retracts the lead leg to deny shin-to-shin connection.","response":"Follow with a technical stand-up or switch to the opposite leg instead of reaching with the upper body.","sort":20},{"type":"Guard Systems","block":"Seated Guard","technique":"Butterfly Entry","name":"Opponent kneels with elbows tight","reaction":"Opponent lowers to both knees and blocks direct underhook access.","response":"Use wrist or collar ties to create elbow separation, then insert the butterfly hooks while staying upright.","sort":30},{"type":"Guard Systems","block":"Seated Guard","technique":"Arm Drag","name":"Opponent pulls the elbow back","reaction":"Opponent retracts the arm and squares the shoulder as the drag starts.","response":"Follow the retraction to the near leg or collar tie rather than overextending the drag.","sort":40},{"type":"Guard Systems","block":"Seated Guard","technique":"Single Leg Wrestle-Up","name":"Opponent sprawls on the shoulders","reaction":"Opponent drives the hips back and chest down as you connect to the leg.","response":"Keep the head inside, build to a knee and turn the corner instead of trying to stand straight up.","sort":50},{"type":"Guard Systems","block":"Seated Guard","technique":"DLR Entry","name":"Opponent keeps the knee turned inward","reaction":"Opponent rotates the lead knee inward to make the outside hook difficult.","response":"Control the ankle, create a slight external angle and insert the hook only after the knee line opens.","sort":60},{"type":"Guard Systems","block":"Seated Guard","technique":"Single Leg X Entry","name":"Opponent squares both feet","reaction":"Opponent keeps a square stance and hides the near hip line.","response":"Off-balance first with shin-to-shin or arm drag, then enter underneath the leg as the weight transfers.","sort":70},{"type":"Passing","block":"Headquarters Passing","technique":"Headquarters Entry","name":"Opponent keeps both knees outside","reaction":"Opponent frames with the knees and prevents you from stepping into the central position.","response":"Control one ankle or knee line, create an angle and enter headquarters only after opening the space between the legs.","sort":10},{"type":"Passing","block":"Headquarters Passing","technique":"Inside Position Control","name":"Opponent pummels the inside knee back","reaction":"Opponent recovers inside knee position and begins squaring the hips.","response":"Pin the near thigh, keep head and shoulder position and repummel your knee before progressing.","sort":20},{"type":"Passing","block":"Headquarters Passing","technique":"Knee Cut from Headquarters","name":"Opponent frames the shoulder","reaction":"Opponent places a strong frame on the near shoulder and turns onto the side.","response":"Clear or redirect the frame, win the underhook/crossface line and cut only after upper-body control is available.","sort":30},{"type":"Passing","block":"Headquarters Passing","technique":"Smash Pass from Headquarters","name":"Opponent turns the knees away","reaction":"Opponent rotates both knees to the far side to avoid the knee cut.","response":"Follow the hip rotation, staple the legs together and settle weight before advancing around the knees.","sort":40},{"type":"Passing","block":"Headquarters Passing","technique":"Leg Drag from Headquarters","name":"Opponent straightens the near leg","reaction":"Opponent extends the leg to prevent you from folding it across the body.","response":"Control above the knee, shift the hip angle and redirect the leg rather than pulling from the ankle.","sort":50},{"type":"Passing","block":"Headquarters Passing","technique":"Backstep from Headquarters","name":"Opponent captures the backstepping leg","reaction":"Opponent closes half guard around the leg as you rotate.","response":"Keep upper-body control, clear the knee line deliberately and finish from reverse half rather than rushing the turn.","sort":60},{"type":"Passing","block":"Headquarters Passing","technique":"Long Step Pass","name":"Opponent follows with the hips","reaction":"Opponent hip-escapes in the same direction and tries to keep the knees between you.","response":"Control the far hip or upper body and redirect the long step so the shoulders cannot square with the hips.","sort":70},{"type":"Passing","block":"Body Lock Passing","technique":"Body Lock Entry","name":"Opponent frames both shoulders","reaction":"Opponent posts straight arms on the shoulders to deny chest connection.","response":"Clear one frame at a time, win head position and connect below the elbows before locking the hands.","sort":10},{"type":"Passing","block":"Body Lock Passing","technique":"Head Position & Hip Connection","name":"Opponent turns the head and shoulders away","reaction":"Opponent angles the torso to weaken your head position and create a hip escape lane.","response":"Re-center the head, keep the hips connected and follow the shoulder turn before advancing the knees.","sort":20},{"type":"Passing","block":"Body Lock Passing","technique":"Butterfly Flattening","name":"Opponent keeps strong double hooks","reaction":"Opponent elevates the knees and tries to keep your hips light.","response":"Widen the base, lower the hips and walk the hooks to one side before attempting to flatten the shoulders.","sort":30},{"type":"Passing","block":"Body Lock Passing","technique":"Double-Under Body Lock","name":"Opponent keeps elbows inside the knees","reaction":"Opponent wedges the elbows between the knees and prevents the hands from connecting.","response":"Use head position and hip pressure to narrow the knees, then connect the lock under the elbow line.","sort":40},{"type":"Passing","block":"Body Lock Passing","technique":"Knee Pin Finish","name":"Opponent turns the knee back inside","reaction":"Opponent recovers the knee line while you are trying to pin the legs.","response":"Control the hip, repummel the passing knee and settle the pin before moving the upper body.","sort":50},{"type":"Passing","block":"Body Lock Passing","technique":"Half Guard Finish","name":"Opponent closes the legs around one of yours","reaction":"Opponent catches half guard as the body-lock pass nears completion.","response":"Keep chest and head control, free the knee before the ankle and finish without giving up upper-body pressure.","sort":60},{"type":"Passing","block":"Body Lock Passing","technique":"Back Take Transition","name":"Opponent turns away under pressure","reaction":"Opponent rotates toward turtle to avoid being flattened.","response":"Follow the shoulder line, maintain waist connection and establish seatbelt or hip control before inserting hooks.","sort":70},{"type":"Passing","block":"Leg Drag Passing","technique":"Leg Drag Entry","name":"Opponent retracts the knee to chest","reaction":"Opponent pulls the leg back before it can be redirected across the hips.","response":"Control above the knee, step closer and use the opposite leg or hip angle to reopen the drag line.","sort":10},{"type":"Passing","block":"Leg Drag Passing","technique":"Hip Control & Pin","name":"Opponent turns the hips toward you","reaction":"Opponent rotates the hips inward to recover square guard.","response":"Block the far hip, keep the dragged knee across the center line and settle shoulder position before progressing.","sort":20},{"type":"Passing","block":"Leg Drag Passing","technique":"Side-to-Side Leg Drag","name":"Opponent recovers the far hook","reaction":"Opponent inserts the far foot or hook as you switch drag direction.","response":"Control the far knee first, clear the hook and then change sides without releasing hip connection.","sort":30},{"type":"Passing","block":"Leg Drag Passing","technique":"DLR Leg Drag","name":"Opponent maintains a strong DLR hook","reaction":"Opponent keeps the outside hook active and pulls your lead leg into the guard.","response":"Clear the hook at the ankle/knee line, square your base and only then redirect the leg across the body.","sort":40},{"type":"Passing","block":"Leg Drag Passing","technique":"X Guard Leg Drag","name":"Opponent extends the X hooks","reaction":"Opponent stretches the legs to keep your hips away and prevent the leg drag angle.","response":"Collapse one hook, control the knee line and step outside the extension before dragging the leg.","sort":50},{"type":"Passing","block":"Leg Drag Passing","technique":"Knee Cut Transition","name":"Opponent squares the hips during the drag","reaction":"Opponent turns back toward you and recovers an inside knee line.","response":"Use the recovered knee line as your knee-cut channel while keeping upper-body control.","sort":60},{"type":"Passing","block":"Leg Drag Passing","technique":"Back Take Transition","name":"Opponent turns away from the hip pin","reaction":"Opponent rotates toward turtle to avoid the pass.","response":"Follow behind the hip, keep control of the near thigh and connect the upper body before releasing the legs.","sort":70},{"type":"Escapes","block":"Knee-on-Belly Escapes","technique":"Frame & Hip Escape","name":"Opponent drives the knee deeper across the abdomen","reaction":"Opponent increases knee pressure and controls the far upper body.","response":"Frame the shin and hip, turn slightly onto the side and move the hips away before trying to recover the knee.","sort":10},{"type":"Escapes","block":"Knee-on-Belly Escapes","technique":"Elbow-Knee Recovery","name":"Opponent blocks the near hip","reaction":"Opponent controls the near hip with the hand and prevents the knee from returning inside.","response":"Clear the hip control first, connect elbow to knee and recover guard through the available side.","sort":20},{"type":"Escapes","block":"Knee-on-Belly Escapes","technique":"Bridge to Guard Recovery","name":"Opponent posts wide during the bridge","reaction":"Opponent widens the hands and base to absorb the bridge.","response":"Use the post to create lateral space, turn the hips and recover the knee rather than trying to reverse the position.","sort":30},{"type":"Escapes","block":"Knee-on-Belly Escapes","technique":"Underhook Escape","name":"Opponent crossfaces while keeping knee pressure","reaction":"Opponent controls the head to stop you turning under the torso.","response":"Frame the neck, create head movement first and only then pummel the underhook while turning onto the side.","sort":40},{"type":"Escapes","block":"Knee-on-Belly Escapes","technique":"Single Leg Recovery","name":"Opponent steps the knee away","reaction":"Opponent retracts the knee-on-belly leg as you connect to it.","response":"Follow to the ankle or far leg, build to the elbow and convert the escape into a wrestle-up rather than chasing from flat.","sort":50},{"type":"Escapes","block":"North-South Escapes","technique":"Frame & Hip Turn","name":"Opponent controls both elbows high","reaction":"Opponent pins the upper arms and prevents direct framing on the torso.","response":"Create a small shoulder bridge, recover one elbow inside and turn the hips only after rebuilding a frame.","sort":10},{"type":"Escapes","block":"North-South Escapes","technique":"Elbow Escape","name":"Opponent follows the hip movement","reaction":"Opponent walks around the head as your hips move and keeps chest alignment.","response":"Change direction, frame the near shoulder and create an elbow-knee connection before the opponent can settle again.","sort":20},{"type":"Escapes","block":"North-South Escapes","technique":"Underhook Recovery","name":"Opponent hides the near elbow","reaction":"Opponent keeps the arm tight and blocks your path to an underhook.","response":"Use frames to move the chest first, then pummel under the shoulder once the elbow line separates.","sort":30},{"type":"Escapes","block":"North-South Escapes","technique":"Pendulum Escape","name":"Opponent widens the knees","reaction":"Opponent spreads the base to resist your pendulum movement.","response":"Increase shoulder-to-hip rotation and use the swing to create guard-recovery space rather than trying to roll the opponent.","sort":40},{"type":"Escapes","block":"North-South Escapes","technique":"Turtle Recovery","name":"Opponent follows toward the back","reaction":"Opponent stays connected as you turn and begins reaching for the seatbelt.","response":"Protect the neck, keep the near elbow tight and complete the turn to a safe turtle before exposing the far side.","sort":50},{"type":"Escapes","block":"Front Headlock Escapes","technique":"Posture & Hand Fight","name":"Opponent pulls the head below the hips","reaction":"Opponent snaps the head down and connects chest weight over the shoulders.","response":"Rebuild a strong base, control the choking wrist or arm and recover head height before trying to move around.","sort":10},{"type":"Escapes","block":"Front Headlock Escapes","technique":"Two-on-One Wrist Peel","name":"Opponent reinforces the choking hand","reaction":"Opponent connects the second hand and tightens the grip around the neck.","response":"Use both hands on the primary choking wrist, create neck space first and then turn toward the safe side.","sort":20},{"type":"Escapes","block":"Front Headlock Escapes","technique":"Guard Pull Recovery","name":"Opponent circles toward the back","reaction":"Opponent starts moving around the corner while maintaining front-headlock control.","response":"Keep one knee between the bodies, follow the angle and sit to a connected guard before the back is exposed.","sort":30},{"type":"Escapes","block":"Front Headlock Escapes","technique":"Peek-Out","name":"Opponent blocks the near elbow","reaction":"Opponent controls the near arm and prevents you from clearing the shoulder line.","response":"Create forward pressure to lighten the arm, then turn the shoulder through only when the elbow can pass.","sort":40},{"type":"Escapes","block":"Front Headlock Escapes","technique":"Sit-Out","name":"Opponent follows the hips","reaction":"Opponent circles with the sit-out and keeps chest pressure over the shoulders.","response":"Post the far hand, extend the hips farther and turn the head and shoulders toward the opponent before recovering base.","sort":50},{"type":"Escapes","block":"Front Headlock Escapes","technique":"Single Leg Re-Attack","name":"Opponent stands tall after losing chest pressure","reaction":"Opponent raises the torso but keeps the hands near the head and shoulders.","response":"Use the posture change to connect to the near leg, keep the head inside and transition immediately to a wrestling finish.","sort":60},{"type":"Escapes","block":"Front Headlock Escapes","technique":"Roll-Through Escape","name":"Opponent overcommits weight to one side","reaction":"Opponent drives shoulder pressure heavily across one side of the neck and upper back.","response":"Trap the committed side, roll through the available shoulder line and recover position without exposing the neck during the rotation.","sort":70},{"type":"Submissions","block":"Turtle Attacks","technique":"Turtle Breakdown to Side Control","name":"Opponent keeps elbows and knees tightly connected","reaction":"Opponent forms a compact turtle and denies direct access to the hips.","response":"Control the near elbow and hip line, create an angle and break the structure before trying to flatten the torso.","sort":10},{"type":"Submissions","block":"Turtle Attacks","technique":"Seatbelt Entry","name":"Opponent protects both sides of the neck","reaction":"Opponent keeps the hands high and elbows tight while staying compact.","response":"Secure chest-to-back connection and shoulder control first, then establish seatbelt without reaching across open space.","sort":20},{"type":"Submissions","block":"Turtle Attacks","technique":"Back Take","name":"Opponent rolls to one hip","reaction":"Opponent sits to a hip to prevent hooks and tries to face you.","response":"Follow the hip, control the far shoulder and insert the first hook only after stopping the turn-in.","sort":30},{"type":"Submissions","block":"Turtle Attacks","technique":"Spiral Ride","name":"Opponent builds one foot to stand","reaction":"Opponent posts one foot and starts rising from turtle.","response":"Use the spiral control to load the far shoulder, block the standing hip and return the opponent to a controlled base.","sort":40},{"type":"Submissions","block":"Turtle Attacks","technique":"Clock Choke","name":"Opponent grabs the choking sleeve","reaction":"Opponent controls the sleeve or wrist to stop the collar pressure from tightening.","response":"Keep the collar grip, control the far hip or arm and circle only after the defensive grip is neutralized.","sort":50},{"type":"Submissions","block":"Turtle Attacks","technique":"Crucifix Entry","name":"Opponent hides the near arm","reaction":"Opponent tucks the near elbow under the chest to prevent arm isolation.","response":"Use hip and shoulder control to expose the elbow first, then trap the arm before rotating to the crucifix.","sort":60},{"type":"Submissions","block":"Turtle Attacks","technique":"Anaconda Transition","name":"Opponent turns inward from turtle","reaction":"Opponent rotates toward you and exposes the arm-and-neck channel.","response":"Capture the arm-and-neck connection during the turn, keep chest pressure and finish the transition only after the shoulder is controlled.","sort":70},{"type":"Takedowns","block":"Takedowns","technique":"Arm Drag to Single Leg","name":"Opponent retracts the dragged arm","reaction":"Opponent pulls the elbow back and squares the shoulders.","response":"Follow the retraction into the near leg, keep head position and connect the single before the stance resets.","sort":210},{"type":"Takedowns","block":"Takedowns","technique":"Duck Under","name":"Opponent lowers the elbow to block the turn","reaction":"Opponent clamps the near elbow and prevents the shoulder from passing underneath.","response":"Create upward pressure on the tie, step deeper and turn only after the elbow line opens.","sort":220},{"type":"Takedowns","block":"Takedowns","technique":"Snapdown to Go Behind","name":"Opponent posts both hands on the mat","reaction":"Opponent catches the snapdown on the hands and tries to square back up.","response":"Keep head-and-arm control, circle toward the exposed hip and secure the go-behind before posture returns.","sort":230},{"type":"Takedowns","block":"Takedowns","technique":"Knee Tap","name":"Opponent widens the far leg","reaction":"Opponent steps the target knee away and lowers the hips.","response":"Maintain upper-body control and switch direction to a trip or body lock rather than reaching farther for the knee.","sort":240},{"type":"Takedowns","block":"Takedown Defense / Counters","technique":"Sprawl to Front Headlock","name":"Opponent builds back to the knees","reaction":"Opponent recovers the knees after the sprawl and starts lifting the head.","response":"Keep chest pressure over the shoulders and connect chin-and-arm control before attacking or circling behind.","sort":210},{"type":"Takedowns","block":"Takedown Defense / Counters","technique":"Whizzer Kick Counter","name":"Opponent drives through the underhook","reaction":"Opponent keeps forward pressure and tries to finish the single or body lock despite the whizzer.","response":"Use the whizzer to turn the shoulder line, block the near leg and time the kick as the opponent steps.","sort":220},{"type":"Takedowns","block":"Takedown Defense / Counters","technique":"Single Leg Granby Escape","name":"Opponent follows the leg through the roll","reaction":"Opponent stays attached to the captured leg and tries to follow the granby.","response":"Protect the knee line, continue the shoulder rotation and recover facing position before standing.","sort":230},{"type":"Guard Systems","block":"Closed Guard","technique":"Flower Sweep","name":"Opponent posts the far hand","reaction":"Opponent posts wide to stop the rotational sweep.","response":"Control or redirect the post, maintain the leg angle and finish only after the far base is removed.","sort":210},{"type":"Guard Systems","block":"Closed Guard","technique":"Pendulum Sweep","name":"Opponent widens the knees","reaction":"Opponent spreads the base and keeps the hips heavy to resist the pendulum.","response":"Increase the side angle, control the arm and use the pendulum leg to move the hips before finishing the rotation.","sort":220},{"type":"Guard Systems","block":"Closed Guard","technique":"Cross-Collar Choke","name":"Opponent protects the second collar grip","reaction":"Opponent controls the free hand or tucks the chin to deny the finishing grip.","response":"Keep the first grip deep, angle the torso and clear the hand fight before inserting the second grip.","sort":230},{"type":"Guard Systems","block":"Closed Guard","technique":"Omoplata","name":"Opponent rolls forward","reaction":"Opponent somersaults to relieve shoulder pressure and avoid being flattened.","response":"Follow the roll, keep control of the arm and settle into top position or re-attack before releasing the shoulder line.","sort":240},{"type":"Guard Systems","block":"Closed Guard","technique":"Hip Bump to Kimura","name":"Opponent posts the hand to stop the sweep","reaction":"Opponent extends the near hand to the mat as the hip-bump starts.","response":"Capture the posting wrist immediately, connect the figure-four and control posture before attacking the shoulder.","sort":250},{"type":"Guard Systems","block":"Sit Up Guard","technique":"Sit Up Collar Drag","name":"Opponent pulls the collar-side shoulder back","reaction":"Opponent retracts the gripped shoulder and tries to square the hips.","response":"Keep the collar connection, angle outside the knee line and use the retreat to enter the back or single-leg path.","sort":210},{"type":"Guard Systems","block":"Sit Up Guard","technique":"Sit Up Wrestle-Up","name":"Opponent sprawls as you rise","reaction":"Opponent drives the hips back and chest down when you connect to the leg.","response":"Keep the head inside, build from elbow to hand and turn the corner before trying to stand fully.","sort":220},{"type":"Guard Systems","block":"De La Riva","technique":"Sickle Sweep","name":"Opponent lifts the targeted heel","reaction":"Opponent removes weight from the leg you planned to reap.","response":"Use the light leg to redirect the foot and combine the sweep with technical stand-up or tripod mechanics.","sort":210},{"type":"Guard Systems","block":"De La Riva","technique":"DLR to Shin-to-Shin","name":"Opponent squares the hips and removes the DLR hook","reaction":"Opponent turns the knee inward and clears the outside hook.","response":"Keep ankle connection, sit up and place the shin inside as the opponent squares instead of chasing the lost hook.","sort":220},{"type":"Guard Systems","block":"Deep De La Riva","technique":"Deep DLR to Waiter Guard","name":"Opponent bends the trapped knee","reaction":"Opponent lowers the base and brings the heel closer to the hips.","response":"Follow the leg underneath, connect to the far leg and transition to waiter control while keeping the knee line managed.","sort":210},{"type":"Guard Systems","block":"Deep De La Riva","technique":"Deep DLR to Leg Drag","name":"Opponent turns the hips away","reaction":"Opponent rotates away from the deep hook and exposes the outside hip.","response":"Follow the rotation, control the knee line and guide the legs across into the leg-drag angle.","sort":220},{"type":"Guard Systems","block":"Shallow Guard","technique":"Wrestle-Up Transition","name":"Opponent retreats from the shallow guard","reaction":"Opponent moves the hips backward and removes close guard connection.","response":"Follow to the leg with posture, build to a knee and convert the retreat into a wrestling finish.","sort":210},{"type":"Guard Systems","block":"Shallow Guard","technique":"Shallow to Single Leg X","name":"Opponent steps the near leg deeper","reaction":"Opponent closes distance with the lead leg and puts more weight over it.","response":"Use the committed step to enter underneath the hip and connect the Single Leg X structure.","sort":220},{"type":"Guard Systems","block":"Waiter Guard","technique":"Waiter to Leg Drag","name":"Opponent turns the knee outward during the sweep","reaction":"Opponent rotates the trapped leg and exposes the far hip.","response":"Keep control of the knee line and redirect the legs across the body into the leg-drag position.","sort":210},{"type":"Guard Systems","block":"Waiter Guard","technique":"Waiter to Deep Half","name":"Opponent drops the hips low","reaction":"Opponent lowers the hips and makes the waiter elevation difficult.","response":"Follow underneath the center of gravity and transition to deep-half control before the upper body settles.","sort":220},{"type":"Guard Systems","block":"Double Pull / Berimbolo","technique":"Baby Bolo Entry","name":"Opponent sits with one knee high","reaction":"Opponent settles to a seated guard with one knee creating a barrier to the full inversion.","response":"Control the ankle and hip, use the shallow inversion angle and enter behind the hip without forcing full rotation.","sort":210},{"type":"Guard Systems","block":"Double Pull / Berimbolo","technique":"Crab Ride Back Take","name":"Opponent turns to face you from crab ride","reaction":"Opponent rotates the shoulders toward you and tries to clear the hooks.","response":"Control the far hip, switch the hooks with the turn and climb to chest-to-back connection before attacking the seatbelt.","sort":220},{"type":"Guard Systems","block":"Butterfly Guard","technique":"Shoulder Crunch Sweep","name":"Opponent posts the far hand","reaction":"Opponent uses the free hand to widen the base and stop the shoulder-crunch elevation.","response":"Keep the trapped shoulder connected, redirect the post and rotate underneath the center of gravity before finishing.","sort":210},{"type":"Guard Systems","block":"Butterfly Guard","technique":"Elevation Sweep","name":"Opponent keeps hips far back","reaction":"Opponent retracts the hips to reduce weight over the butterfly hooks.","response":"Sit up into upper-body connection, pull the weight forward and elevate only after the hips return over the hooks.","sort":220},{"type":"Guard Systems","block":"Butterfly Guard","technique":"Guillotine Entry","name":"Opponent drives the head low between the shoulders","reaction":"Opponent pressures forward with the neck exposed while trying to flatten the guard.","response":"Control the chin line, keep hip distance and connect the guillotine before the shoulders are pinned.","sort":230},{"type":"Guard Systems","block":"Half Guard","technique":"Underhook Knee Tap Sweep","name":"Opponent posts the far leg","reaction":"Opponent widens the far leg while maintaining the whizzer.","response":"Keep the underhook and head position, come higher to the dogfight and redirect to the posted leg or back take.","sort":210},{"type":"Guard Systems","block":"Half Guard","technique":"John Wayne Sweep","name":"Opponent shifts the hips away from the trapped knee","reaction":"Opponent moves weight off the controlled side to prevent the rotational sweep.","response":"Use the weight transfer to create space for the underhook or knee shield instead of forcing the rotation.","sort":220},{"type":"Guard Systems","block":"Half Guard","technique":"Lockdown Sweep","name":"Opponent posts both hands forward","reaction":"Opponent widens the upper-body base while the legs remain entangled.","response":"Use the lockdown to move the hips first, then attack the upper-body base or transition to the underhook rather than lifting straight up.","sort":230},{"type":"Guard Systems","block":"Deep Half Guard","technique":"Deep Half to Single Leg","name":"Opponent stands to escape deep half","reaction":"Opponent lifts the hips and begins freeing the trapped leg.","response":"Follow the leg, keep the head close to the hip and come up to the single before the foot is fully withdrawn.","sort":210},{"type":"Guard Systems","block":"Deep Half Guard","technique":"Deep Half to X Guard","name":"Opponent keeps a tall staggered stance","reaction":"Opponent posts the far foot and keeps the hips high to avoid the deep-half sweep.","response":"Use the space under the hips to insert the second hook and transition to X Guard control.","sort":220},{"type":"Guard Systems","block":"Collar Sleeve Guard","technique":"Arm Drag","name":"Opponent retracts the sleeve arm","reaction":"Opponent pulls the controlled arm back and turns the shoulder toward you.","response":"Maintain collar control, follow the elbow line and angle toward the back or near leg.","sort":210},{"type":"Guard Systems","block":"Collar Sleeve Guard","technique":"Tomoe Nage Sweep","name":"Opponent drives weight forward","reaction":"Opponent leans into the collar-sleeve connection and brings the hips closer.","response":"Place the lifting foot with posture control and use the forward commitment to elevate rather than pulling with the arms.","sort":220},{"type":"Guard Systems","block":"Lasso Guard","technique":"Lasso to Single Leg X","name":"Opponent stands and straightens the lasso-side leg","reaction":"Opponent raises the hips and creates space under the near leg while trying to free the sleeve.","response":"Maintain sleeve control, invert or angle under the hip and connect Single Leg X before releasing the lasso.","sort":210},{"type":"Guard Systems","block":"Lasso Guard","technique":"Lasso to Leg Drag Sweep","name":"Opponent turns away from the lasso","reaction":"Opponent rotates the hips away to reduce shoulder pressure from the lasso.","response":"Use the rotation to redirect the legs, keep sleeve control and come up into the leg-drag angle.","sort":220},{"type":"Guard Systems","block":"Reverse De La Riva","technique":"RDLR to Single Leg X","name":"Opponent steps the free leg closer","reaction":"Opponent brings the secondary leg near while trying to clear the reverse hook.","response":"Control the near ankle, switch hip angle and enter Single Leg X under the newly available base.","sort":210},{"type":"Guard Systems","block":"Reverse De La Riva","technique":"RDLR Wrestle-Up","name":"Opponent retreats from the inversion threat","reaction":"Opponent moves the hips backward and removes close reverse-DLR pressure.","response":"Sit up immediately, connect to the near leg and build posture before the opponent fully disengages.","sort":220},{"type":"Guard Systems","block":"Single Leg X","technique":"SLX Technical Stand-Up","name":"Opponent pulls the trapped leg backward","reaction":"Opponent tries to withdraw the leg while keeping balance on the far foot.","response":"Maintain ankle connection, sit up with the retreat and stand into the leg rather than extending away.","sort":210},{"type":"Guard Systems","block":"Single Leg X","technique":"SLX to Wrestle-Up","name":"Opponent clears the inside hook but leaves the ankle controlled","reaction":"Opponent removes the hip connection yet keeps the lead foot within reach.","response":"Keep the ankle, build to a knee and convert the guard exchange into a single-leg finish.","sort":220},{"type":"Guard Systems","block":"X Guard","technique":"X Guard Knee Tap","name":"Opponent widens the far leg","reaction":"Opponent creates a broad stance to prevent the standard sweep.","response":"Use the hook extension to expose the near knee, come up and tap the knee while controlling the upper leg.","sort":210},{"type":"Guard Systems","block":"X Guard","technique":"X Guard to Leg Drag","name":"Opponent turns the knee outward while stepping free","reaction":"Opponent rotates the leg to clear the hooks and exposes the outside hip.","response":"Follow the knee line, redirect the leg across and come up into the leg-drag control.","sort":220},{"type":"Passing","block":"Open Guard Passing","technique":"X-Pass","name":"Opponent tracks the passing leg with the knee","reaction":"Opponent follows your outside step and keeps the knee pointed toward your torso.","response":"Control the ankle and knee line, exaggerate the angle and clear the hips before settling chest pressure.","sort":210},{"type":"Passing","block":"Open Guard Passing","technique":"Long Step","name":"Opponent hip-escapes in the same direction","reaction":"Opponent follows the long step with the hips and tries to recover the knees.","response":"Control the far hip or upper body and redirect the step so the shoulders cannot square with the pelvis.","sort":220},{"type":"Passing","block":"Open Guard Passing","technique":"Folding Pass","name":"Opponent frames the near shoulder","reaction":"Opponent uses the forearm to prevent chest pressure while the knees are folded.","response":"Clear the frame, keep the knees pinned together and settle the upper body before advancing.","sort":230},{"type":"Passing","block":"De La Riva Passing","technique":"Shin Staple","name":"Opponent pummels the DLR hook back inside","reaction":"Opponent recovers the outside hook as you try to pin the shin.","response":"Keep ankle control, adjust the staple angle and clear the hook before moving the upper body.","sort":210},{"type":"Passing","block":"De La Riva Passing","technique":"Headquarters Transition","name":"Opponent squares the hips after grip removal","reaction":"Opponent recovers neutral stance once the DLR grips are broken.","response":"Step into central inside position immediately and establish headquarters before the guard is rebuilt.","sort":220},{"type":"Passing","block":"Under-Over Passing","technique":"Double Under Transition","name":"Opponent brings both knees toward the chest","reaction":"Opponent retracts the legs and blocks the under-over angle.","response":"Connect under both legs, control the hips and move the shoulders forward before stacking.","sort":210},{"type":"Passing","block":"Under-Over Passing","technique":"Leg Drag Finish","name":"Opponent turns the hips away from the under-over","reaction":"Opponent rotates to relieve shoulder pressure and exposes the outside hip.","response":"Guide the top leg across, follow the hip turn and finish in leg-drag control rather than forcing the original path.","sort":220},{"type":"Passing","block":"Half Guard Passing","technique":"Reverse Half Guard Pass","name":"Opponent turns inward from reverse half","reaction":"Opponent rotates toward you and tries to insert the knee between the bodies.","response":"Control the far hip and shoulder, block the knee line and clear your trapped leg before changing chest direction.","sort":210},{"type":"Passing","block":"Half Guard Passing","technique":"Mount Transition","name":"Opponent keeps the near elbow tight during the pass","reaction":"Opponent prevents direct side-control settlement by framing close to the ribs.","response":"Keep crossface control, slide the knee across the hips and establish mount before releasing the trapped leg.","sort":220},{"type":"Escapes","block":"Side Control Escapes","technique":"Running Man / Defensive Shell","name":"Opponent follows behind the shoulders","reaction":"Opponent stays attached as you turn away and begins reaching for back control.","response":"Keep elbows and knees connected, protect the neck and use hip movement to recover guard before opening the shell.","sort":210},{"type":"Escapes","block":"Side Control Escapes","technique":"Elbow Push Escape","name":"Opponent posts the near hand on the mat","reaction":"Opponent bases with the near arm while keeping chest pressure across the torso.","response":"Redirect the posted elbow across the center line, turn the shoulders and create space to recover the knees.","sort":220},{"type":"Escapes","block":"Mount Escapes","technique":"Back Door Escape","name":"Opponent climbs to high mount","reaction":"Opponent moves the knees toward the shoulders and reduces hip control.","response":"Protect the arms, create hip space underneath and slide the body toward the opening behind the opponent's legs.","sort":210},{"type":"Escapes","block":"Mount Escapes","technique":"Heel Drag Recovery","name":"Opponent keeps one knee low beside the hip","reaction":"Opponent blocks the knee-elbow escape with a low, tight knee position.","response":"Use the heel to drag the trapped leg line, create space and reinsert the knee before the mount tightens again.","sort":220},{"type":"Escapes","block":"Back Escapes","technique":"Turn-In Escape","name":"Opponent loses chest-to-back alignment","reaction":"Opponent's upper body drifts to one side while maintaining the seatbelt.","response":"Win the head position, put the shoulder to the mat and turn into the open side before the alignment is recovered.","sort":210},{"type":"Escapes","block":"Back Escapes","technique":"Body Triangle Escape","name":"Opponent locks the triangle on the top side","reaction":"Opponent connects the body triangle with the locking foot accessible near the hip.","response":"Protect the neck first, move toward the lock side and free the hip line before attacking the feet.","sort":220},{"type":"Escapes","block":"Turtle Escapes / Recovery","technique":"Stand-Up Recovery","name":"Opponent stays behind the hips without hooks","reaction":"Opponent controls the waist from turtle but has not established hooks or seatbelt.","response":"Build one foot, protect hand control and stand while keeping the hips below the opponent's chest.","sort":210},{"type":"Escapes","block":"Turtle Escapes / Recovery","technique":"Switch / Sit-Out Reversal","name":"Opponent reaches across one shoulder","reaction":"Opponent overcommits an arm around the torso while following the turtle.","response":"Trap the reaching arm, sit the hips through and turn toward the opponent to reverse or recover facing position.","sort":220},{"type":"Submissions","block":"Back Attacks","technique":"Straightjacket Control","name":"Opponent hides one hand under the chin","reaction":"Opponent keeps one defensive hand high while the other controls your choking wrist.","response":"Trap the lower hand first, keep chest-to-back alignment and isolate the remaining defensive hand before attacking the neck.","sort":210},{"type":"Submissions","block":"Back Attacks","technique":"Body Triangle Control","name":"Opponent turns toward the lock","reaction":"Opponent rotates the hips toward the locking side to create space in the triangle.","response":"Follow the hip line, keep knees connected and adjust the lock before continuing upper-body attacks.","sort":220},{"type":"Submissions","block":"Back Attacks","technique":"Rear Triangle","name":"Opponent turns inside the seatbelt","reaction":"Opponent rotates the shoulders toward you and places one arm across the center line.","response":"Control the exposed arm, bring the leg over the shoulder line and lock the triangle only after head-and-arm alignment is secured.","sort":230},{"type":"Submissions","block":"Front Headlock","technique":"Snapdown Entry","name":"Opponent stands upright with elbows inside","reaction":"Opponent maintains tall posture and denies direct access to the neck.","response":"Create forward pressure or hand fighting first, then snap when the opponent reacts upward or steps into range.","sort":210},{"type":"Submissions","block":"Front Headlock","technique":"Chin Strap Go Behind","name":"Opponent posts the near hand","reaction":"Opponent uses the near hand to block your circle toward the back.","response":"Control the posting arm or elbow, maintain chin-strap pressure and circle only after clearing the barrier.","sort":220},{"type":"Submissions","block":"Side Control Attacks","technique":"Baseball Bat Choke","name":"Opponent turns toward you to recover guard","reaction":"Opponent faces inward and brings the near arm between the bodies.","response":"Keep the collar grips, control the shoulder line and rotate around the head only after preventing guard recovery.","sort":210},{"type":"Submissions","block":"Side Control Attacks","technique":"Knee-on-Belly Transition","name":"Opponent frames at the hip","reaction":"Opponent creates a near-side hip frame while turning onto the side.","response":"Control or clear the frame, place the knee across the torso and keep the far hip controlled during the transition.","sort":220},{"type":"Submissions","block":"Mount Attacks","technique":"Mounted Triangle","name":"Opponent pushes one knee with the near arm","reaction":"Opponent extends an arm inside while trying to create space for the knee-elbow escape.","response":"Control the wrist and elbow, climb the knee above the shoulder and rotate into the triangle before the arm retracts.","sort":210},{"type":"Submissions","block":"Mount Attacks","technique":"Gift Wrap Back Take","name":"Opponent turns onto the side and protects the neck","reaction":"Opponent exposes the far arm while turning to escape mount.","response":"Connect the gift wrap, maintain chest pressure and follow the turn into the back-take angle before releasing mount.","sort":220},{"type":"Submissions","block":"North-South Attacks","technique":"Paper Cutter Transition","name":"Opponent turns from north-south toward side control","reaction":"Opponent rotates the face and shoulders inward while trying to recover a standard side position.","response":"Keep collar and elbow control, settle beside the shoulder and establish the paper-cutter angle before applying pressure.","sort":210},{"type":"Submissions","block":"North-South Attacks","technique":"Head-and-Arm Transition","name":"Opponent brings the near arm across the neck line","reaction":"Opponent frames across your chest and exposes the head-and-arm connection.","response":"Trap the arm against the head, move to the correct side and settle the shoulder line before finishing the transition.","sort":220}]$json$::jsonb;
  v_row jsonb;
  v_type_id uuid;
  v_block_id uuid;
  v_technique_id uuid;
  v_type_name text;
  v_block_name text;
  v_technique_name text;
  v_name text;
  v_reaction text;
  v_response text;
  v_sort integer;
begin
  for v_row in
    select value from jsonb_array_elements(v_seed)
  loop
    v_type_name := btrim(v_row ->> 'type');
    v_block_name := btrim(v_row ->> 'block');
    v_technique_name := btrim(v_row ->> 'technique');
    v_name := btrim(v_row ->> 'name');
    v_reaction := btrim(v_row ->> 'reaction');
    v_response := nullif(btrim(v_row ->> 'response'), '');
    v_sort := coalesce((v_row ->> 'sort')::integer, 100);

    select t.id
      into v_type_id
    from public.coach_curriculum_types t
    where lower(t.name) = lower(v_type_name)
    order by t.is_active desc, t.created_at asc
    limit 1;

    if v_type_id is null then
      raise notice 'ATOM Curriculum V3: skipping situation "%" because type "%" is missing.', v_name, v_type_name;
      continue;
    end if;

    select b.id
      into v_block_id
    from public.coach_curriculum_blocks b
    where lower(b.name) = lower(v_block_name)
    order by
      case when b.type_id = v_type_id then 0 else 1 end,
      b.is_active desc,
      b.created_at asc
    limit 1;

    if v_block_id is null then
      raise notice 'ATOM Curriculum V3: skipping situation "%" because block "%" is missing.', v_name, v_block_name;
      continue;
    end if;

    select ct.id
      into v_technique_id
    from public.coach_curriculum_techniques ct
    where ct.block_id = v_block_id
      and lower(ct.name) = lower(v_technique_name)
    order by ct.is_active desc, ct.created_at asc
    limit 1;

    if v_technique_id is null then
      raise notice 'ATOM Curriculum V3: skipping situation "%" because technique "%" is missing.', v_name, v_technique_name;
      continue;
    end if;

    if not exists (
      select 1
      from public.coach_curriculum_situations cs
      where cs.technique_id = v_technique_id
        and lower(cs.name) = lower(v_name)
    ) then
      insert into public.coach_curriculum_situations (
        technique_id, name, opponent_reaction, coaching_response, sort_order, is_active
      )
      values (
        v_technique_id, v_name, v_reaction, v_response, v_sort, true
      );
    end if;
  end loop;
end
$atom_curriculum_v3_situations$;

commit;
